1	/**
2	 * Streams the audit-log CSV; requires `activity:export`.
3	 *
4	 * Owner D. `activity:export` sits above `activity:read` in `ROLE_MATRIX` —
5	 * reading the feed in the UI and walking off with the whole audit trail are
6	 * different privileges.
7	 *
8	 * Must call (do not reimplement): can, isEnabled, toCsv
9	 */
10	
11	import { errorResponse, failure } from "@/app/api/_lib/responses";
12	import { getActor } from "@/lib/actor";
13	import { csvResponseHeaders, toCsv } from "@/lib/csv";
14	import { isEnabled } from "@/lib/feature-flags";
15	import { can } from "@/lib/permissions";
16	import { exportActivitySchema } from "@/schemas/activity";
17	import { listActivity } from "@/server/services/activity-service";
18	import { buildFlagContext } from "@/server/services/feature-flag-service";
19	import { getOrganizationSummary } from "@/server/services/organization-service";
20	import type { ActivityEvent } from "@/types/activity";
21	
22	export const dynamic = "force-dynamic";
23	
24	const EXPORT_PAGE_LIMIT = 100;
25	
26	const COLUMNS: readonly string[] = [
27	  "occurredAt",
28	  "action",
29	  "actorId",
30	  "subjectKind",
31	  "subjectId",
32	  "projectId",
33	  "summary",
34	];
35	
36	export async function GET(request: Request): Promise<Response> {
37	  try {
38	    const url = new URL(request.url);
39	    const orgSlug = url.searchParams.get("orgSlug");
40	    if (orgSlug === null) {
41	      return failure("validation_failed", "orgSlug is required.");
42	    }
43	
44	    const actor = await getActor(orgSlug);
45	    const { organization } = await getOrganizationSummary(actor, actor.orgId);
46	
47	    if (!can(actor, "activity:export", { kind: "activity", orgId: actor.orgId })) {
48	      return failure("forbidden", "Exporting the audit log requires an admin.");
49	    }
50	
51	    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
52	      return failure("forbidden", "CSV export is not included in this plan.");
53	    }
54	
55	    const parsed = exportActivitySchema.safeParse({
56	      orgId: actor.orgId,
57	      since: url.searchParams.get("since"),
58	      until: url.searchParams.get("until"),
59	      format: url.searchParams.get("format") ?? "csv",
60	    });
61	    if (!parsed.success) {
62	      return failure(
63	        "validation_failed",
64	        "since and until must be ISO-8601 timestamps.",
65	      );
66	    }
67	
68	    const page = await listActivity(actor, {
69	      orgId: parsed.data.orgId,
70	      since: parsed.data.since,
71	      until: parsed.data.until,
72	      limit: EXPORT_PAGE_LIMIT,
73	    });
74	
75	    if (parsed.data.format === "json") {
76	      return Response.json({ items: page.items, total: page.total });
77	    }
78	
79	    const csv = toCsv(page.items.map(toRow), COLUMNS);
80	    return new Response(csv, {
81	      headers: csvResponseHeaders(`taskflow-activity-${organization.slug}.csv`),
82	    });
83	  } catch (error) {
84	    return errorResponse(error);
85	  }
86	}
87	
88	function toRow(
89	  event: ActivityEvent,
90	): Record<string, string | number | boolean | null> {
91	  return {
92	    occurredAt: event.occurredAt,
93	    action: event.action,
