/**
 * Walks every page of `since`..`until` (inclusive) for `orgId`, newest first,
 * so the export never silently caps at one page's worth of rows.
 */
async function listAllActivity(
  orgId: OrgId,
  since: IsoTimestamp,
  until: IsoTimestamp,
): Promise<ActivityEvent[]> {
  const items: ActivityEvent[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await activityRepo.listActivity({
      orgId,
      since,
      until,
      limit: 100,
      cursor,
    });
    items.push(...page.items);
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
  }

  return items;
}

